def expected_tokens_per_step(alpha: float, k: int) -> float:
    """Expected tokens per target-model pass: (1 - alpha^(k+1)) / (1 - alpha)."""
    numerator = 1 - alpha ** (k + 1)
    denominator = 1 - alpha
    return round(numerator / denominator, 2)

print(expected_tokens_per_step(0.8, 4))
